"""Lazy, composable iterable transformations for glom specifications."""

import itertools

from boltons.iterutils import chunked_iter, split_iter, windowed_iter

from .core import (T, SKIP, STOP, Path, TargetRegistry, CheckError,
                   _MISSING, glom)


class First(object):
    """Return the first item matching *key*, or *default* if none match.

    *key* is a glom spec evaluated against each item, defaulting to a
    truthiness check of the item itself.
    """
    def __init__(self, key=T, default=None):
        self.key = key
        self.default = default

    def glomit(self, target, scope):
        iterate = scope[TargetRegistry].get_handler('iterate', target,
                                                    path=scope[Path])
        for item in iterate(target):
            if _matches(item, self.key, scope):
                return item
        return self.default

    def __repr__(self):
        return 'First(%r, default=%r)' % (self.key, self.default)


def _matches(item, spec, scope):
    try:
        value = scope[glom](item, spec, scope)
    except CheckError:
        return False
    return value is not SKIP and value is not STOP and bool(value)


class Iter(object):
    """Apply a spec lazily to items, optionally chaining stream operations.

    For example, ``Iter('price').filter(lambda p: p > 0).all()`` extracts
    positive prices into a list. Without ``all()``, evaluation returns an
    iterator. Chaining does not modify the original Iter instance.
    """
    def __init__(self, subspec=T, sentinel=STOP):
        self.subspec = subspec
        self.sentinel = sentinel
        self._operations = ()

    def _chain(self, name, *args):
        result = type(self)(self.subspec, sentinel=self.sentinel)
        result._operations = self._operations + ((name, args),)
        return result

    def map(self, subspec):
        """Evaluate *subspec* against each item."""
        return self._chain('map', subspec)

    def filter(self, key=T):
        """Keep items for which the *key* spec returns a truthy value."""
        return self._chain('filter', key)

    def chunked(self, size, fill=_MISSING):
        """Group items into lists of *size*, optionally padding the last."""
        if not isinstance(size, int) or size < 1:
            raise ValueError('expected a positive integer chunk size')
        return self._chain('chunked', size, fill)

    def windowed(self, size):
        """Yield overlapping tuples of *size* items."""
        if not isinstance(size, int) or size < 1:
            raise ValueError('expected a positive integer window size')
        return self._chain('windowed', size)

    def split(self, sep=None, maxsplit=None):
        """Split the stream into lists separated by *sep*."""
        return self._chain('split', sep, maxsplit)

    def flatten(self):
        """Flatten one level of nested iterables."""
        return self._chain('flatten')

    def unique(self, key=T):
        """Keep the first item for each distinct *key* result."""
        return self._chain('unique', key)

    def slice(self, *args):
        """Lazily slice the stream using itertools.islice conventions."""
        # Validate immediately, without consuming the eventual target.
        itertools.islice((), *args)
        return self._chain('slice', *args)

    def limit(self, count):
        """Keep at most *count* items."""
        return self.slice(count)

    def takewhile(self, key=T):
        """Keep items until the *key* spec becomes false."""
        return self._chain('takewhile', key)

    def dropwhile(self, key=T):
        """Drop initial items while the *key* spec is true."""
        return self._chain('dropwhile', key)

    def all(self):
        """Materialize this stream into a list."""
        return (self, list)

    def first(self, key=T, default=None):
        """Return the first matching item, or *default*."""
        return (self, First(key, default=default))

    def _iterate(self, target, spec, scope):
        iterate = scope[TargetRegistry].get_handler('iterate', target,
                                                    path=scope[Path])
        for index, item in enumerate(iterate(target)):
            child = scope.new_child({Path: scope[Path] + [index]})
            value = scope[glom](item, spec, child)
            if value is self.sentinel:
                break
            if value is not SKIP:
                yield value

    def _flatten(self, iterator, scope):
        for item in iterator:
            iterate = scope[TargetRegistry].get_handler('iterate', item,
                                                        path=scope[Path])
            for value in iterate(item):
                yield value

    def _unique(self, iterator, key, scope):
        seen = set()
        for item in iterator:
            value = scope[glom](item, key, scope)
            if value not in seen:
                seen.add(value)
                yield item

    def glomit(self, target, scope):
        iterator = self._iterate(target, self.subspec, scope)
        for name, args in self._operations:
            if name == 'map':
                iterator = self._iterate(iterator, args[0], scope)
            elif name in ('filter', 'takewhile', 'dropwhile'):
                predicate = lambda item, key=args[0]: _matches(item, key, scope)
                if name == 'filter':
                    iterator = filter(predicate, iterator)
                else:
                    iterator = getattr(itertools, name)(predicate, iterator)
            elif name == 'chunked':
                size, fill = args
                kwargs = {} if fill is _MISSING else {'fill': fill}
                iterator = chunked_iter(iterator, size, **kwargs)
            elif name == 'windowed':
                iterator = windowed_iter(iterator, *args)
            elif name == 'split':
                iterator = split_iter(iterator, *args)
            elif name == 'flatten':
                iterator = self._flatten(iterator, scope)
            elif name == 'unique':
                iterator = self._unique(iterator, args[0], scope)
            elif name == 'slice':
                iterator = itertools.islice(iterator, *args)
        return iterator

    def __repr__(self):
        result = 'Iter(%r)' % (self.subspec,)
        for name, args in self._operations:
            result += '.%s(%s)' % (name, ', '.join(repr(arg) for arg in args))
        return result
